"""Validate template footprints/domains for every topology variant."""
import json, sys
sys.path.insert(0, '/workspace/tmp')
import reference
from fuzz_fast import run_engine

VARIANTS = [
    ['clos', 4, 'tor', 0], ['clos', 4, 'tor', 1], ['clos', 6, 'pod', 0], ['clos', 6, 'pod', 1],
    ['clos', 8, 'tor', 1], ['clos', 4, 'pod', 1],
    ['leaf-spine', 2, 1], ['leaf-spine', 3, 2], ['leaf-spine', 5, 3],
    ['torus2d', 3, 'host'], ['torus2d', 3, 'row'], ['torus2d', 4, 'host'], ['torus2d', 5, 'row'],
    ['torus3d', 3, 'host'], ['torus3d', 3, 'line'],
    ['dragonfly', 2, 1, 1, 'router'], ['dragonfly', 3, 2, 1, 'group'], ['dragonfly', 3, 2, 1, 'target'],
    ['dragonfly', 5, 2, 2, 'target'], ['dragonfly', 4, 1, 3, 'group'],
    ['dragonfly-plus', 2, 1, 1, 1, 1, 'tor'], ['dragonfly-plus', 2, 1, 1, 1, 0, 'group'],
    ['dragonfly-plus', 3, 2, 1, 2, 1, 'tor'], ['dragonfly-plus', 3, 2, 3, 1, 0, 'group'],
    ['dragonfly-plus', 4, 1, 3, 1, 1, 'group'],
]

def build_session(spec):
    topo = reference.Topology(spec)
    # one group per distinct domain, one task per template of that domain
    domains = {}
    for i, d in enumerate(topo.domains):
        domains.setdefault(d, []).append(i)
    groups = []
    tasks = []
    for gi, (dom, tids) in enumerate(sorted(domains.items())):
        groups.append([1, 10 ** 12])
        for tid in tids:
            tasks.append([tid, gi, 1, dom, 0])
    state = reference.State(topo, [0] * topo.n, groups, tasks)
    use = state.usage()
    caps = [u + 1 for u in use]
    return {'topology': spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': {'groups': list(range(len(groups))), 'nodes': list(range(topo.n)), 'tasks': []},
            'transactions': []}

def main():
    sessions = [build_session(spec) for spec in VARIANTS]
    request = {'version': 2, 'sessions': sessions}
    try:
        expected = reference.run(request)
    except ValueError as exc:
        print('reference rejected:', exc); return 1
    actual = run_engine(request)
    if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
        for i, (a, e) in enumerate(zip(actual['sessions'], expected['sessions'])):
            if json.dumps(a, sort_keys=True) != json.dumps(e, sort_keys=True):
                print('MISMATCH session', i, VARIANTS[i])
                for key in ('nodes', 'templates'):
                    if a[key] != e[key]: print('  ', key, a[key], e[key])
                ag = {tuple(r[:1] + r[5:]) for r in a['initial']['groups']}
                eg = {tuple(r[:1] + r[5:]) for r in e['initial']['groups']}
                print('  group diffs (id,fp,dom,class):', sorted(ag ^ eg)[:10])
                an = {r[0]: r[1] for r in a['initial']['nodes']}
                en = {r[0]: r[1] for r in e['initial']['nodes']}
                print('  node usage diffs:', {k: (an[k], en[k]) for k in an if an[k] != en[k]})
                break
        return 1
    print('all %d topology variants match' % len(VARIANTS))
    return 0

raise SystemExit(main())
